    @Override
    public void setupAnim(LivingEntityRenderState state) {
        super.setupAnim(state);
        float pos = state.walkAnimationPos;
        float speed = state.walkAnimationSpeed;
        this.head.yRot += state.yRot * ((float) Math.PI / 180F) * 0.6F;
        this.head.xRot += state.xRot * ((float) Math.PI / 180F) * 0.6F;
        this.leftLeg.xRot += Mth.cos(pos * 0.6662F) * 1.0F * speed;
        this.rightLeg.xRot += Mth.cos(pos * 0.6662F + (float) Math.PI) * 1.0F * speed;
    }
